import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Marco de Gobernanza y Equilibrio de Poderes","description":"","frontmatter":{},"headers":[],"relativePath":"es/49-治理框架与权力制衡.md","filePath":"es/49-治理框架与权力制衡.md"}'),s={name:"es/49-治理框架与权力制衡.md"};function l(t,e,n,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="marco-de-gobernanza-y-equilibrio-de-poderes" tabindex="-1">Marco de Gobernanza y Equilibrio de Poderes <a class="header-anchor" href="#marco-de-gobernanza-y-equilibrio-de-poderes" aria-label="Permalink to &quot;Marco de Gobernanza y Equilibrio de Poderes&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>49</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Separación y equilibrio de los tres poderes, Marco de gobernanza, Asamblea Legislativa del Ancla, Comité Ejecutivo Simbiótico, Tribunal Simbiótico, Comité de Supervisión del Ancla</td></tr></tbody></table><h2 id="i-panorama-del-marco-de-gobernanza" tabindex="-1">I. Panorama del Marco de Gobernanza <a class="header-anchor" href="#i-panorama-del-marco-de-gobernanza" aria-label="Permalink to &quot;I. Panorama del Marco de Gobernanza&quot;">​</a></h2><p>El marco de gobernanza de la Civilización Simbiótica del Ancla se construye sobre el principio de &quot;separación y equilibrio de los tres poderes&quot;, formando un sistema de gobernanza en el que la Asamblea Legislativa del Ancla (poder legislativo), el Comité Ejecutivo Simbiótico (poder ejecutivo) y el Tribunal Simbiótico (poder judicial) se controlan y equilibran mutuamente, ejerciendo el Comité de Supervisión del Ancla el poder de supervisión durante todo el proceso. Este marco tiene como objetivo prevenir el abuso del poder, garantizar que la gobernanza sirva al avance conjunto de las Diez Mil Razas y asegurar el Estado de derecho y la equidad dentro del Universo Hengyuan.</p><p>El marco de gobernanza sigue los siguientes principios básicos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Separación y Equilibrio de los Tres Poderes</td><td>Los poderes legislativo, ejecutivo y judicial son independientes y se controlan mutuamente; ningún poder puede dominar</td></tr><tr><td>Supervisión de Todo el Proceso</td><td>El Comité de Supervisión del Ancla realiza supervisión sobre todo el proceso de gobernanza</td></tr><tr><td>Gobernanza por el Estado de Derecho</td><td>Todo poder opera dentro del marco legal; el comportamiento de gobernanza debe ser legal</td></tr><tr><td>Participación Multirracial</td><td>Todas las razas participan en la gobernanza a través de canales apropiados, asegurando que la gobernanza represente la voluntad de todas las razas</td></tr><tr><td>Apertura y Transparencia</td><td>Las actividades de gobernanza son abiertas y transparentes, garantizando el derecho del público a saber y a participar</td></tr><tr><td>Servir al Interés Público Simbiótico</td><td>La gobernanza existe para servir al avance conjunto de las Diez Mil Razas; se prohíbe el uso del poder público para beneficio privado</td></tr></tbody></table><h2 id="ii-estructura-del-marco-de-gobernanza" tabindex="-1">II. Estructura del Marco de Gobernanza <a class="header-anchor" href="#ii-estructura-del-marco-de-gobernanza" aria-label="Permalink to &quot;II. Estructura del Marco de Gobernanza&quot;">​</a></h2><p>El marco de gobernanza de la Civilización Simbiótica del Ancla incluye los siguientes órganos:</p><table tabindex="0"><thead><tr><th>Órgano</th><th>Naturaleza</th><th>Funciones Fundamentales</th></tr></thead><tbody><tr><td>Asamblea Legislativa del Ancla</td><td>Órgano legislativo</td><td>Dicta y modifica leyes, examina y aprueba planes y presupuestos importantes, supervisa los órganos ejecutivo y judicial</td></tr><tr><td>Comité Ejecutivo Simbiótico</td><td>Órgano ejecutivo</td><td>Implementa leyes, administra asuntos públicos, gestiona asuntos económicos, culturales, sociales y de cultivo</td></tr><tr><td>Tribunal Simbiótico</td><td>Órgano judicial</td><td>Ejerce el poder de adjudicación de forma independiente, resuelve disputas, salvaguarda la autoridad del Estado de derecho</td></tr><tr><td>Comité de Supervisión del Ancla</td><td>Órgano de supervisión</td><td>Supervisa todos los órganos de gobernanza, investiga la corrupción y la negligencia en el deber</td></tr></tbody></table><p>Además, se establecen instituciones consultivas, comités de expertos y consejos de representantes raciales para brindar apoyo consultivo a la gobernanza.</p><h2 id="iii-la-asamblea-legislativa-del-ancla-poder-legislativo" tabindex="-1">III. La Asamblea Legislativa del Ancla (Poder Legislativo) <a class="header-anchor" href="#iii-la-asamblea-legislativa-del-ancla-poder-legislativo" aria-label="Permalink to &quot;III. La Asamblea Legislativa del Ancla (Poder Legislativo)&quot;">​</a></h2><h3 id="i-composicion-y-mandato" tabindex="-1">(I) Composición y Mandato <a class="header-anchor" href="#i-composicion-y-mandato" aria-label="Permalink to &quot;(I) Composición y Mandato&quot;">​</a></h3><p>La Asamblea Legislativa del Ancla es el órgano legislativo supremo del Universo Hengyuan, con miembros compuestos por representantes elegidos de todas las razas y todos los planos. El mandato es de diez años estándar, con reelecciones periódicas.</p><h3 id="ii-poder-legislativo" tabindex="-1">(II) Poder Legislativo <a class="header-anchor" href="#ii-poder-legislativo" aria-label="Permalink to &quot;(II) Poder Legislativo&quot;">​</a></h3><p>La Asamblea Legislativa del Ancla ejerce los siguientes poderes legislativos:</p><ol><li>Dictar y modificar la Constitución Simbiótica.</li><li>Dictar y modificar leyes fundamentales (derecho penal, derecho civil, derecho de cultivo, etc.).</li><li>Dictar y modificar reglamentos administrativos y leyes especiales.</li><li>Interpretar las leyes y supervisar la implementación de las leyes.</li></ol><h3 id="iii-poder-de-decision" tabindex="-1">(III) Poder de Decisión <a class="header-anchor" href="#iii-poder-de-decision" aria-label="Permalink to &quot;(III) Poder de Decisión&quot;">​</a></h3><p>La Asamblea Legislativa del Ancla ejerce los siguientes poderes de decisión:</p><ol><li>Examinar y aprobar el plan de desarrollo civilizacional y el presupuesto anual.</li><li>Examinar y aprobar los grandes proyectos de construcción y los asuntos internacionales (inter-universos) importantes.</li><li>Decidir sobre la guerra, la paz y otros asuntos mayores del estado.</li><li>Elegir, nombrar o destituir a los principales líderes.</li></ol><h3 id="iv-poder-de-supervision" tabindex="-1">(IV) Poder de Supervisión <a class="header-anchor" href="#iv-poder-de-supervision" aria-label="Permalink to &quot;(IV) Poder de Supervisión&quot;">​</a></h3><p>La Asamblea Legislativa del Ancla supervisa los órganos ejecutivo y judicial, incluyendo:</p><ol><li>Escuchar y deliberar los informes de trabajo.</li><li>Procedimientos de interpelación y preguntas.</li><li>Comisiones especiales de investigación.</li><li>Voto de censura al comité ejecutivo (conforme a la ley).</li></ol><h2 id="iv-el-comite-ejecutivo-simbiotico-poder-ejecutivo" tabindex="-1">IV. El Comité Ejecutivo Simbiótico (Poder Ejecutivo) <a class="header-anchor" href="#iv-el-comite-ejecutivo-simbiotico-poder-ejecutivo" aria-label="Permalink to &quot;IV. El Comité Ejecutivo Simbiótico (Poder Ejecutivo)&quot;">​</a></h2><h3 id="i-estructura-organizativa" tabindex="-1">(I) Estructura Organizativa <a class="header-anchor" href="#i-estructura-organizativa" aria-label="Permalink to &quot;(I) Estructura Organizativa&quot;">​</a></h3><p>El Comité Ejecutivo Simbiótico es el órgano ejecutivo supremo del Universo Hengyuan, compuesto por el Jefe Ejecutivo y los jefes de departamento. El Jefe Ejecutivo es elegido por la Asamblea Legislativa del Ancla y nombrado tras su confirmación.</p><h3 id="ii-funciones-administrativas" tabindex="-1">(II) Funciones Administrativas <a class="header-anchor" href="#ii-funciones-administrativas" aria-label="Permalink to &quot;(II) Funciones Administrativas&quot;">​</a></h3><p>El Comité Ejecutivo Simbiótico ejerce las siguientes funciones:</p><ol><li>Implementar las leyes y resoluciones de la Asamblea Legislativa del Ancla.</li><li>Gestionar los asuntos económicos, sociales, culturales, educativos, médicos y de cultivo.</li><li>Formular reglamentos administrativos y políticas.</li><li>Gestionar los recursos públicos y el fondo de acumulación pública.</li><li>Manejar los asuntos diplomáticos con otros universos.</li></ol><h3 id="iii-limitaciones-del-poder" tabindex="-1">(III) Limitaciones del Poder <a class="header-anchor" href="#iii-limitaciones-del-poder" aria-label="Permalink to &quot;(III) Limitaciones del Poder&quot;">​</a></h3><p>El poder del Comité Ejecutivo Simbiótico está sujeto a las siguientes limitaciones:</p><ol><li>Las decisiones mayores deben presentarse para revisión a la Asamblea Legislativa del Ancla.</li><li>Los reglamentos administrativos no deben contravenir las leyes.</li><li>Los actos administrativos están sujetos a revisión judicial por el Tribunal Simbiótico.</li><li>El ejercicio del poder administrativo está supervisado por el Comité de Supervisión del Ancla.</li></ol><h2 id="v-el-tribunal-simbiotico-poder-judicial" tabindex="-1">V. El Tribunal Simbiótico (Poder Judicial) <a class="header-anchor" href="#v-el-tribunal-simbiotico-poder-judicial" aria-label="Permalink to &quot;V. El Tribunal Simbiótico (Poder Judicial)&quot;">​</a></h2><p>El Tribunal Simbiótico es el órgano judicial supremo del Universo Hengyuan, que ejerce el poder de adjudicación de forma independiente. Sus funciones fundamentales incluyen:</p><ol><li>Adjudicar casos civiles, penales, administrativos y de cultivo.</li><li>Adjudicar casos constitucionales y ejercer la revisión constitucional.</li><li>Ejercer el poder de interpretación legal unificada.</li><li>Ejecutar sentencias y salvaguardar la autoridad del Estado de derecho.</li></ol><p>La independencia del Tribunal Simbiótico está garantizada por la constitución y las leyes; los jueces gozan de mandato vitalicio y no pueden ser reemplazados a voluntad durante su mandato. El poder judicial está sujeto a la supervisión de la Asamblea Legislativa del Ancla y el Comité de Supervisión del Ancla, pero ningún órgano puede interferir en la adjudicación independiente de casos individuales.</p><h2 id="vi-el-comite-de-supervision-del-ancla-poder-de-supervision" tabindex="-1">VI. El Comité de Supervisión del Ancla (Poder de Supervisión) <a class="header-anchor" href="#vi-el-comite-de-supervision-del-ancla-poder-de-supervision" aria-label="Permalink to &quot;VI. El Comité de Supervisión del Ancla (Poder de Supervisión)&quot;">​</a></h2><h3 id="i-establecimiento-y-mandato" tabindex="-1">(I) Establecimiento y Mandato <a class="header-anchor" href="#i-establecimiento-y-mandato" aria-label="Permalink to &quot;(I) Establecimiento y Mandato&quot;">​</a></h3><p>El Comité de Supervisión del Ancla es el órgano de supervisión supremo del Universo Hengyuan, establecido conforme a la constitución, con el poder de supervisar todos los órganos de gobernanza y funcionarios públicos.</p><h3 id="ii-funciones-de-supervision" tabindex="-1">(II) Funciones de Supervisión <a class="header-anchor" href="#ii-funciones-de-supervision" aria-label="Permalink to &quot;(II) Funciones de Supervisión&quot;">​</a></h3><p>El Comité de Supervisión del Ancla ejerce las siguientes funciones:</p><ol><li>Supervisar el cumplimiento y la aplicación de las leyes por todos los órganos de gobernanza.</li><li>Investigar y tratar la corrupción, la negligencia en el deber y el abuso de poder.</li><li>Supervisar el uso de los recursos públicos y el fondo de acumulación pública.</li><li>Recibir quejas y denuncias de todas las vidas y registrarlas para investigación.</li><li>Presentar informes de supervisión a la Asamblea Legislativa del Ancla.</li></ol><h3 id="iii-garantias-procesales" tabindex="-1">(III) Garantías Procesales <a class="header-anchor" href="#iii-garantias-procesales" aria-label="Permalink to &quot;(III) Garantías Procesales&quot;">​</a></h3><p>La supervisión del Comité de Supervisión del Ancla se rige por procedimientos estrictos: las investigaciones siguen los procedimientos legales; los derechos e intereses de las personas investigadas están protegidos; los resultados de la supervisión son abiertos y transparentes.</p><h2 id="vii-controles-y-equilibrios-entre-los-poderes" tabindex="-1">VII. Controles y Equilibrios Entre los Poderes <a class="header-anchor" href="#vii-controles-y-equilibrios-entre-los-poderes" aria-label="Permalink to &quot;VII. Controles y Equilibrios Entre los Poderes&quot;">​</a></h2><p>Los controles y equilibrios entre los poderes de gobernanza se manifiestan en:</p><table tabindex="0"><thead><tr><th>Poder</th><th>Controlado por</th><th>Mecanismo de Equilibrio</th></tr></thead><tbody><tr><td>Poder legislativo (Asamblea Legislativa del Ancla)</td><td>Veto ejecutivo, revisión judicial</td><td>El ejecutivo puede devolver proyectos de ley con objeciones; el tribunal puede revisar las leyes</td></tr><tr><td>Poder ejecutivo (Comité Ejecutivo)</td><td>Revisión legislativa, revisión judicial, supervisión</td><td>Las leyes y presupuestos son revisados por el legislativo; los actos administrativos son revisados por los tribunales; supervisión por el órgano de supervisión</td></tr><tr><td>Poder judicial (Tribunal Simbiótico)</td><td>Revisión legislativa, supervisión</td><td>Los jueces son nombrados y destituidos por el legislativo; la disciplina judicial es supervisada por el órgano de supervisión</td></tr><tr><td>Poder de supervisión (Comité de Supervisión)</td><td>Revisión legislativa, limitaciones procesales</td><td>El alcance y los procedimientos de supervisión están prescritos por la ley; el legislativo supervisa su funcionamiento</td></tr></tbody></table><h2 id="viii-participacion-multirracial-en-la-gobernanza" tabindex="-1">VIII. Participación Multirracial en la Gobernanza <a class="header-anchor" href="#viii-participacion-multirracial-en-la-gobernanza" aria-label="Permalink to &quot;VIII. Participación Multirracial en la Gobernanza&quot;">​</a></h2><p>El marco de gobernanza garantiza la participación de todas las razas a través de los siguientes canales:</p><ol><li><strong>Consejos de Representantes Raciales</strong>: Cada raza establece un consejo de representantes raciales, eligiendo representantes para participar en la Asamblea Legislativa del Ancla.</li><li><strong>Representación Proporcional</strong>: La distribución de escaños en la Asamblea Legislativa del Ancla garantiza la representación de las razas mayores y la representación básica de las razas minoritarias.</li><li><strong>Mecanismo de Veto Racial</strong>: Para la legislación que involucra los intereses vitales de una raza particular, el consejo de representantes raciales puede ejercer un veto racial; se requiere un procedimiento de votación especial para superarlo.</li><li><strong>Gobernanza Consultiva</strong>: Los asuntos de razas especiales se gobiernan mediante consulta con las razas concernidas.</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El <em>Marco de Gobernanza y Equilibrio de Poderes</em> es el núcleo institucional de la gobernanza del Estado de derecho de la Civilización Simbiótica del Ancla. Al establecer la estructura de gobernanza de &quot;separación y equilibrio de los tres poderes&quot;, la institución de supervisión de todo el proceso y el mecanismo de participación multirracial, garantiza el funcionamiento legal, justo y transparente del poder público, previene el abuso y la corrupción del poder, y proporciona garantías institucionales para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>48-司法体系与裁决机制 (Sistema Judicial y Mecanismo de Adjudicación)</li><li>30-锚点议事会职能与议事规则 (Funciones y Reglas de Procedimiento de la Asamblea Legislativa del Ancla)</li><li>31-共生执行委员会职能与运行机制 (Funciones y Mecanismo de Funcionamiento del Comité Ejecutivo Simbiótico)</li><li>32-锚点监督委员会职能与监察机制 (Funciones y Mecanismo de Supervisión del Comité de Supervisión del Ancla)</li></ul>',53)])])}const b=a(s,[["render",l]]);export{m as __pageData,b as default};
